stepxmp.pre:
note {
    display: block;
    position: relative;
}
note > tag {
    position: absolute;
    top: 0;
    right: 0;
}

banner {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 18pt;
    background: #c81e00;
    color: white;
}
guide {
    display: block;
    padding-top: 26pt;
    box-decoration-break: clone;
}

guide { writing-mode: vertical-rl; }
seal {
    position: fixed;
    inset-block-start: 0;
    inset-inline-start: 0;
}
